mkdir -p src/store && cat > src/store/memoryStore.js << 'EOF'
const users = [];
const payments = [];

// Get all users
function getUsers() {
  return users;
}

// Get a user by ID
function getUser(id) {
  return users.find(u => u.id === id);
}

// Create a user
function createUser(data) {
  const user = {
    id: Math.random().toString(36).substr(2),
    ...data,
    createdAt: new Date(),
    updatedAt: new Date()
  };
  users.push(user);
  return user;
}

// Update a user
function updateUser(id, data) {
  const user = users.find(u => u.id === id);
  if (user) {
    Object.assign(user, data);
    user.updatedAt = new Date();
  }
  return user;
}

// Delete a user
function deleteUser(id) {
  const user = users.find(u => u.id === id);
  if (user) {
    users = users.filter(u => u.id !== id);
  }
  return user;
}

// Get all payments
function getPayments() {
  return payments;
}

// Get a payment by ID
function getPayment(id) {
  return payments.find(p => p.id === id);
}

// Create a payment
function createPayment(data) {
  const payment = {
    id: Math.random().toString(36).substr(2),
    ...data,
    createdAt: new Date(),
    updatedAt: new Date()
  };
  payments.push(payment);
  return payment;
}

// Update a payment
function updatePayment(id, data) {
  const payment = getPayment(id);
  if (payment) {
    Object.assign(payment, data);
    payment.updatedAt = new Date();
  }
  return payment;
}

// Delete a payment
function deletePayment(id) {
  const payment = getPayment(id);
  if (payment) {
    payments = payments.filter(p => p.id !== id);
  }
  return payment;
}

module.exports = {
  users,
  payments,
  getUsers,
  getUser,
  createUser,
  updateUser,
  deleteUser,
  getPayments,
  getPayment,
  createPayment,
  updatePayment,
  deletePayment
};
EOF

